params.command:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Join-Path $env:TEMP 'mhw-updater-e2e-artifacts-60-61'
foreach($b in 60,61){
  $zip=Join-Path $root "$b\MHW-Manual-Mod-Manager-v8.8.4-win-x64.zip"
  $za=[System.IO.Compression.ZipFile]::OpenRead($zip)
  try{
    Write-Output ("===BUILD="+$b+"===")
    $za.Entries | Select-Object -First 80 FullName,Length | ConvertTo-Json -Depth 3
    foreach($n in @('build-identity.json','release-install.json','product-files.json')){
      $e=$za.Entries | Where-Object {$_.FullName -eq $n} | Select-Object -First 1
      if($e){
        $sr=New-Object IO.StreamReader($e.Open())
        try{Write-Output ("---"+$n+"---"); Write-Output $sr.ReadToEnd()} finally{$sr.Dispose()}
      } else {Write-Output ("MISSING="+$n)}
    }
  } finally {$za.Dispose()}
}
